{
 "app_name": "spotify",
 "api_name": "show_playlist_library",
 "path": "/spotify/library/playlists",
 "method": "GET",
 "description": "Search or show a list of playlists in your playlist library.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from spotify app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "query",
   "type": "string",
   "required": false,
   "description": "The search query string.",
   "default": "",
   "constraints": []
  },
  {
   "name": "is_public",
   "type": "boolean",
   "required": false,
   "description": "Whether to show public playlists or private playlists.",
   "default": null,
   "constraints": []
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1, <= 20"
   ]
  },
  {
   "name": "sort_by",
   "type": "string",
   "required": false,
   "description": "The attribute to sort the library playlists by prefixed with +/- to reflect ascending/descending. Valid attributes: created_at and title. If both query and sort_by are given and non-empty, results will be first ranked by query relevance, then paginated, and will then be sorted by the given attribute within each page. If both query and sort_by are not given, null, or empty, sort_by will default to -created_at.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": [
   {
    "playlist_id": 1,
    "title": "string",
    "is_public": true,
    "rating": 0.0,
    "like_count": 1,
    "review_count": 1,
    "owner": {
     "name": "string",
     "email": "user@example.com"
    },
    "created_at": "2019-01-01T00:00:00",
    "song_ids": [
     1
    ]
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}
{
 "app_name": "spotify",
 "api_name": "play_music",
 "path": "/spotify/music_player/play",
 "method": "POST",
 "description": "Play music based on various criteria. You can pass, at most, any one of queue_position, song_id, album_id or playlist_id. If one of song_id, album_id or playlist_id is passed, that song, album or playlist will be added to the queue and played. Otherwise, the queue will remain unchanged. If queue_position is passed, the song at that position in the queue will be played. If none is passed, the current song in the queue will be played.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from spotify app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "song_id",
   "type": "integer",
   "required": false,
   "description": "ID of the song to play.",
   "default": null,
   "constraints": []
  },
  {
   "name": "album_id",
   "type": "integer",
   "required": false,
   "description": "ID of the album to play.",
   "default": null,
   "constraints": []
  },
  {
   "name": "playlist_id",
   "type": "integer",
   "required": false,
   "description": "ID of the playlist to play.",
   "default": null,
   "constraints": []
  },
  {
   "name": "queue_position",
   "type": "integer",
   "required": false,
   "description": "Position of the song in the queue to play.",
   "default": null,
   "constraints": [
    "value >= 0"
   ]
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string",
   "song_id": 1
  },
  "failure": {
   "message": "string"
  }
 }
}

